#!/usr/bin/env bash
# Independent-source FT4 WAV, not generated by FT8AF/FieldOps.
# Credible WSJT-X sample mirrored in its versioned Git repository.
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ft8="$root/app/src/main/cpp/third_party/ft8af/ft8_lib"
test_src="$root/app/src/test/native/ft8af/test_independent_ft4_wav.c"
upstream_sha="2b9d65408debba3f3f2a6a34c8aa33b1308c0f21"
blob_sha="e5cdc88040b477cad842d51c4dd8e5fb6fdbe803"
wav="samples/FT4/000000_000002.wav"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

curl --retry 3 --retry-delay 2 --fail --location --silent --show-error \
  "https://raw.githubusercontent.com/saitohirga/WSJT-X/$upstream_sha/$wav" \
  --output "$tmp/independent_ft4.wav"
test "$(git hash-object "$tmp/independent_ft4.wav")" = "$blob_sha" || {
  echo "FAIL: independent WSJT-X FT4 sample Git blob checksum mismatch" >&2
  exit 1
}
"${CC:-cc}" -std=c11 -O2 -D_GNU_SOURCE -Wall -Wextra -Wno-unused-function \
  -I "$ft8" \
  "$test_src" \
  "$ft8/ft8/pack.c" "$ft8/ft8/encode.c" "$ft8/ft8/crc.c" \
  "$ft8/ft8/constants.c" "$ft8/ft8/text.c" "$ft8/ft8/message.c" \
  "$ft8/ft8/decode.c" "$ft8/ft8/ldpc.c" "$ft8/ft8/osd.c" \
  "$ft8/ft8/unpack.c" "$ft8/common/monitor.c" "$ft8/common/wave.c" \
  "$ft8/fft/kiss_fft.c" "$ft8/fft/kiss_fftr.c" \
  -lm -o "$tmp/ft4_independent_wav_test"
"$tmp/ft4_independent_wav_test" "$tmp/independent_ft4.wav"
echo "Independent WSJT-X source FT4 WAV decode: PASS (not an on-air truth sidecar)"
